const clean = (value, max = 5000) => String(value ?? '').trim().slice(0, max);
const norm = value => String(value ?? '').trim().toLowerCase();

const requestId = clean($json.request_id, 64).toUpperCase();
const customerId = clean($json.customer_id, 64).toUpperCase();
const contactEmail = clean($json.contact_email, 254).toLowerCase();
const subject = clean($json.subject, 200);
const description = clean($json.description, 5000);
const issueCategory = clean($json.issue_category, 64);
const issueSeverity = clean($json.issue_severity, 16);
let aiStatus = clean($json.ai_handling_status, 64) || 'Not Started';
const resolutionType = clean($json.resolution_type, 32) || 'Unresolved';
const resolutionSummary = clean($json.resolution_summary, 2000);
const rawEscalationReason = clean($json.escalation_reason, 100);

const rawApproval = $json.requires_human_approval;
let requiresApproval = rawApproval === true || ['true', 'yes', '1'].includes(norm(rawApproval));

const categories = ['Subscription','Billing','Refund','Account Access','Technical Support','Cancellation','Security','General Question','Other'];
const severities = ['Low','Medium','High','Critical'];
const statuses = ['Not Started','Investigating','Waiting for Tool','Waiting for Approval','Waiting for Customer','Completed','Failed','Escalated'];
const resolutionTypes = ['AI Resolved','Human Resolved','AI + Human','Unresolved'];

const stageByStatus = {
  'Not Started': { id: '4650337004', label: 'New Request' },
  'Investigating': { id: '4650337005', label: 'AI Investigating' },
  'Waiting for Tool': { id: '4650337005', label: 'AI Investigating' },
  'Waiting for Approval': { id: '4650337006', label: 'Human Review' },
  'Waiting for Customer': { id: '4650337007', label: 'Waiting on Customer' },
  'Completed': { id: '4650337008', label: 'Resolved' },
  'Failed': { id: '4650337006', label: 'Human Review' },
  'Escalated': { id: '4650337006', label: 'Human Review' }
};

const severityValue = {
  Low: 'low',
  Medium: 'medium',
  High: 'high',
  Critical: 'critical'
};

const priorityValue = {
  Low: 'LOW',
  Medium: 'MEDIUM',
  High: 'HIGH',
  Critical: 'URGENT'
};

const escalationReasonByInput = {
  'technical complexity': 'technical_complexity',
  technical_complexity: 'technical_complexity',
  'customer request': 'customer_request',
  customer_request: 'customer_request',
  'policy requirement': 'policy_requirement',
  policy_requirement: 'policy_requirement',
  'ai limitation': 'ai_limitation',
  ai_limitation: 'ai_limitation'
};

if (!/^[A-Z0-9][A-Z0-9_-]{4,63}$/.test(requestId)) throw new Error('request_id must be a stable 5-64 character key');
if (!/^[A-Z0-9][A-Z0-9_-]{1,63}$/.test(customerId)) throw new Error('customer_id is invalid');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail)) throw new Error('contact_email is invalid');
if (subject.length < 5) throw new Error('subject must contain at least 5 characters');
if (!description) throw new Error('description is required');
if (!categories.includes(issueCategory)) throw new Error(`Invalid issue_category: ${issueCategory}`);
if (!severities.includes(issueSeverity)) throw new Error(`Invalid issue_severity: ${issueSeverity}`);
if (!statuses.includes(aiStatus)) throw new Error(`Invalid ai_handling_status: ${aiStatus}`);
if (!resolutionTypes.includes(resolutionType)) throw new Error(`Invalid resolution_type: ${resolutionType}`);

if (aiStatus === 'Waiting for Approval') requiresApproval = true;
if (requiresApproval && aiStatus !== 'Waiting for Approval') aiStatus = 'Waiting for Approval';

const needsHumanReview = ['Waiting for Approval', 'Escalated', 'Failed'].includes(aiStatus);
const escalationReason = rawEscalationReason ? escalationReasonByInput[norm(rawEscalationReason)] : '';

if (rawEscalationReason && !escalationReason) {
  throw new Error('escalation_reason must be Technical complexity, Customer request, Policy requirement, or AI limitation');
}
if (needsHumanReview && !escalationReason) {
  throw new Error('escalation_reason is required for Human Review');
}
if (aiStatus === 'Completed' && resolutionType === 'Unresolved') throw new Error('Completed tickets need a resolved resolution_type');
if (aiStatus === 'Completed' && !resolutionSummary) throw new Error('Completed tickets need a resolution_summary');

const stage = stageByStatus[aiStatus];
const input = {
  request_id: requestId,
  customer_id: customerId,
  contact_email: contactEmail,
  subject,
  description,
  issue_category: issueCategory,
  issue_severity: issueSeverity,
  ai_handling_status: aiStatus,
  requires_human_approval: requiresApproval,
  escalation_reason: escalationReason,
  resolution_type: resolutionType,
  resolution_summary: resolutionSummary,
  pipeline_label: 'Enterprise Support',
  pipeline_id: '0',
  pipeline_stage_id: stage.id,
  pipeline_stage_label: stage.label,
  started_at_ms: Date.now()
};

const ticketProperties = {
  subject: input.subject,
  content: input.description,
  hs_pipeline: input.pipeline_id,
  hs_pipeline_stage: input.pipeline_stage_id,
  hs_ticket_priority: priorityValue[input.issue_severity],
  request_id: input.request_id,
  issue_category: input.issue_category,
  issue_severity: severityValue[input.issue_severity],
  ai_handling_status: input.ai_handling_status,
  requires_human_approval: input.requires_human_approval ? 'Yes' : 'No',
  escalation_reason: input.escalation_reason,
  resolution_type: input.resolution_type,
  resolution_summary: input.resolution_summary
};

return { json: {
  input,
  ticket_properties: ticketProperties,
  contact_search_body: {
    filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: input.contact_email }] }],
    properties: ['email','firstname','lastname','customer_id'],
    limit: 2
  },
  ticket_search_body: {
    filterGroups: [{ filters: [{ propertyName: 'request_id', operator: 'EQ', value: input.request_id }] }],
    properties: ['subject','content','hs_pipeline','hs_pipeline_stage','hs_ticket_priority','request_id','issue_category','issue_severity','ai_handling_status','requires_human_approval','escalation_reason','resolution_type','resolution_summary'],
    limit: 2
  }
} };

const config = $('Validate Ticket State').first().json;
const input = config.input;
const contactResponse = $('Find Contact for Ticket').first().json ?? {};
const ticketResponse = $json ?? {};

const contacts = Array.isArray(contactResponse.results) ? contactResponse.results : [];
const tickets = Array.isArray(ticketResponse.results) ? ticketResponse.results : [];

if (contacts.length !== 1) throw new Error(`Expected exactly one HubSpot contact for ${input.contact_email}; found ${contacts.length}`);
if (tickets.length > 1) throw new Error(`Duplicate HubSpot tickets found for request_id ${input.request_id}`);

const existing = tickets[0] ?? null;
const contactId = contacts[0].id;
const createBody = {
  properties: config.ticket_properties,
  associations: [{
    to: { id: contactId },
    types: [{
      associationCategory: 'HUBSPOT_DEFINED',
      associationTypeId: 16
    }]
  }]
};

return { json: {
  http_method: existing ? 'PATCH' : 'POST',
  http_url: existing
    ? `https://api.hubapi.com/crm/objects/2026-09/tickets/${encodeURIComponent(existing.id)}`
    : 'https://api.hubapi.com/crm/objects/2026-09/tickets',
  request_body: existing ? { properties: config.ticket_properties } : createBody,
  action: existing ? 'updated' : 'created',
  previous_ticket_id: existing?.id ?? null,
  contact_id: contactId,
  input
} };

const prepared = $('Prepare Idempotent Upsert').first().json;
const response = $json ?? {};
if (!response.id) throw new Error('HubSpot did not return a ticket ID');

return { json: {
  success: true,
  action: prepared.action,
  ticket_id: response.id,
  request_id: prepared.input.request_id,
  customer_id: prepared.input.customer_id,
  contact_id: prepared.contact_id,
  ai_handling_status: prepared.input.ai_handling_status,
  requires_human_approval: prepared.input.requires_human_approval,
  pipeline: prepared.input.pipeline_label,
  pipeline_stage: prepared.input.pipeline_stage_label,
  verified_by_hubspot_response: true,
  latency_ms: Date.now() - prepared.input.started_at_ms
} };
